package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost;

import java.util.Objects;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * Immutable provenance for one learned mass calibration.
 *
 * <p>
 * Model confidence is intentionally separate from the statistical confidence in {@link EvidenceStateSummary}.
 * Learned-calibrated summaries use a heuristic interval with statistical confidence zero.
 */
@Experimental
public record EvidenceCalibrationSummary(
		double rawRows,
		double finalRows,
		double factor,
		String source,
		long evidenceCount,
		double correctionConfidence,
		String evidenceKey,
		long evidenceRevision) {

	public EvidenceCalibrationSummary {
		requireFiniteNonNegative(rawRows, "rawRows");
		requireFiniteNonNegative(finalRows, "finalRows");
		if (Double.isNaN(factor) || factor < 0.0d) {
			throw new IllegalArgumentException("factor must be nonnegative");
		}
		if (rawRows > 0.0d) {
			if (!Double.isFinite(factor)) {
				throw new IllegalArgumentException("a positive raw estimate requires a finite factor");
			}
			double expected = rawRows * factor;
			if (!approximatelyEqual(expected, finalRows)) {
				throw new IllegalArgumentException("finalRows must equal rawRows multiplied by factor");
			}
		} else if (finalRows > 0.0d && factor != Double.POSITIVE_INFINITY) {
			throw new IllegalArgumentException("a positive prediction from zero raw mass requires an infinite factor");
		}
		source = requireText(source, "source");
		if (evidenceCount <= 0L) {
			throw new IllegalArgumentException("evidenceCount must be positive");
		}
		if (!Double.isFinite(correctionConfidence)
				|| correctionConfidence < 0.0d
				|| correctionConfidence > 1.0d) {
			throw new IllegalArgumentException("correctionConfidence must be in [0, 1]");
		}
		evidenceKey = requireText(evidenceKey, "evidenceKey");
		if (evidenceRevision < 0L) {
			throw new IllegalArgumentException("evidenceRevision must be nonnegative");
		}
	}

	private static void requireFiniteNonNegative(double value, String name) {
		if (!Double.isFinite(value) || value < 0.0d) {
			throw new IllegalArgumentException(name + " must be finite and nonnegative");
		}
	}

	private static String requireText(String value, String name) {
		String normalized = Objects.requireNonNull(value, name).trim();
		if (normalized.isEmpty()) {
			throw new IllegalArgumentException(name + " must not be blank");
		}
		return normalized;
	}

	private static boolean approximatelyEqual(double left, double right) {
		if (Double.doubleToLongBits(left) == Double.doubleToLongBits(right)) {
			return true;
		}
		double scale = Math.max(1.0d, Math.max(Math.abs(left), Math.abs(right)));
		return Math.abs(left - right) <= 8.0d * Math.ulp(scale);
	}
}
